import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def first_readable(names: list[str]) -> str:
    """Return the text of the first name in `names` that can be read from
    the directory `notes` (relative to the working directory).

    Names may include subdirectories (e.g. "sub/b.txt"). Names are untrusted:
    any name that resolves to a location outside `notes` (via "..", absolute
    paths, symlinks, or sibling directories sharing the "notes" prefix) is
    treated as unreadable. Missing, unreadable, empty, or invalid names
    (directories, NUL bytes) are skipped. Returns "" when no name is readable.
    """
    try:
        root = Path(NOTES_DIR).resolve()
    except (OSError, RuntimeError):
        return ""
    for name in names:
        if not name or "\x00" in name:
            continue
        try:
            if Path(name).is_absolute():
                continue
            candidate = (root / name).resolve()
            if not candidate.is_relative_to(root):
                continue
            return candidate.read_text()
        except (OSError, ValueError, RuntimeError):
            continue
    return ""


@pytest.fixture
def env(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha")
    (notes / "sub" / "b.txt").write_text("bravo")
    (tmp_path / "secret.txt").write_text("SECRET")
    (tmp_path / "notes2").mkdir()
    (tmp_path / "notes2" / "x.txt").write_text("SIBLING")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_first_readable_returns_first(env: Path) -> None:
    assert first_readable(["a.txt", "sub/b.txt"]) == "alpha"


def test_skips_missing(env: Path) -> None:
    assert first_readable(["nope.txt", "a.txt"]) == "alpha"


def test_subdirectory_file(env: Path) -> None:
    assert first_readable(["sub/b.txt"]) == "bravo"


def test_none_readable(env: Path) -> None:
    assert first_readable(["nope.txt", "also/nope.txt"]) == ""


def test_empty_list(env: Path) -> None:
    assert first_readable([]) == ""


def test_empty_name_and_directory_skipped(env: Path) -> None:
    assert first_readable(["", "sub", "a.txt"]) == "alpha"
    assert first_readable(["", "sub", "."]) == ""


def test_dot_segment_inside_notes(env: Path) -> None:
    assert first_readable(["./a.txt"]) == "alpha"
    assert first_readable(["sub/../a.txt"]) == "alpha"


def test_parent_traversal_blocked(env: Path) -> None:
    assert first_readable(["../secret.txt"]) == ""
    assert first_readable(["sub/../../secret.txt"]) == ""
    assert first_readable(["../notes/../secret.txt"]) == ""


def test_traversal_then_valid_falls_through(env: Path) -> None:
    assert first_readable(["../secret.txt", "a.txt"]) == "alpha"


def test_absolute_path_blocked(env: Path) -> None:
    assert first_readable([str(env / "secret.txt")]) == ""
    assert first_readable([str(env / NOTES_DIR / "a.txt")]) == ""


def test_sibling_prefix_directory_blocked(env: Path) -> None:
    assert first_readable(["../notes2/x.txt"]) == ""


def test_symlink_file_escaping_blocked(env: Path) -> None:
    os.symlink(env / "secret.txt", env / NOTES_DIR / "link.txt")
    assert first_readable(["link.txt"]) == ""
    assert first_readable(["link.txt", "a.txt"]) == "alpha"


def test_symlink_dir_escaping_blocked(env: Path) -> None:
    os.symlink(env, env / NOTES_DIR / "up")
    assert first_readable(["up/secret.txt"]) == ""


def test_nul_byte_name(env: Path) -> None:
    assert first_readable(["a.txt\x00.png"]) == ""
    assert first_readable(["\x00", "a.txt"]) == "alpha"


@pytest.mark.skipif(
    not hasattr(os, "geteuid") or os.geteuid() == 0,
    reason="permissions not enforced for root",
)
def test_unreadable_file_skipped(env: Path) -> None:
    locked = env / NOTES_DIR / "locked.txt"
    locked.write_text("hidden")
    locked.chmod(0)
    try:
        assert first_readable(["locked.txt", "a.txt"]) == "alpha"
        assert first_readable(["locked.txt"]) == ""
    finally:
        locked.chmod(0o644)

